// fires(spec): spec with every "@fire/<name>" fx script swapped for its program; an unknown name throws
export function fires(spec) {
  if (Array.isArray(spec)) return spec.map(fires);
  if (!spec || typeof spec !== "object") return spec;
  const out = {};
  for (const [k, v] of Object.entries(spec)) {
    if (k === "script" && typeof v === "string" && v.startsWith("@fire/")) { const p = FIRES[v.slice(6)]; if (!p) throw new Error("no fire named " + v); out[k] = p; }
    else out[k] = fires(v);
  }
  return out;
}
